import React, { useState, useEffect, useRef } from "react";
import CollectionPreview from "./collection-preview";
import Explore from "../explore/explore-all";
import FullPageLoader from "../../components/full-page-loader/full-page-loader";
import { connect } from "react-redux";
import { beforeCollection, getCollection } from "../collections/collections.actions";
import { Link } from "react-router-dom";
import { ENV } from "../../config/config";
import { Accordion,Dropdown } from "react-bootstrap";
import Select from 'react-select'
import FilterSearch from "../filter-search/filtersearch";
const { collectionFeaturedImg, userDefaultImg, categoryDefaultImg } = ENV;



const CollectionDetails = (props) => {
  const [collection, setCollection] = useState(null);
  const [nfts, setNfts] = useState(null);
  const [collectionLoader, setColLoader] = useState(true); // collections loader
  const [nftsLoader, setNftsLoader] = useState(true); // NFTs loader
  const nftsRef = useRef(null);

  useEffect(() => {
    window.scroll(0, 0);
    const { collectionId } = props.match.params;
    if (collectionId) props.getCollection(window.atob(collectionId));
    else props.history.push("/collections");
  }, []);

  // when collection data is received
  useEffect(() => {
    if (props.collection.getAuth) {
      const { collection } = props.collection;
      setCollection(collection);
      props.beforeCollection();
      setColLoader(false);
    }
  }, [props.collection.getAuth]);

  const getNftsLoader = (loader) => {
    setNftsLoader(loader);
  };

  return (
    <section
      className="author-area explore-area  popular-collections-area"
      style={{ padding: "0px" }}
    >
      {(collectionLoader || nftsLoader) && <FullPageLoader />}
      <div className="">
        {collection && (
          <div className="d-flex collection-detail-container">
            {/* <div className="col-12 col-md-4">
                            <CollectionPreview collection={collection} />
                        </div> */}
            <div className="collection-preview collection-card">
              <div className="seller">
                <div className="seller-thumb avatar-lg">
                  <img className="rounded-circle" src={collection.logo} alt="Collection Logo" />
                </div>
              </div>
            </div>
            <div className="card-caption col-12 p-0 text-center">
              <div className="card-body pt-0 pb-0">
                <div>
                  <h5 className="mt-3 mb-3">{collection.name}</h5>
                  <p className="mt-3 mb-3">
                    {collection.url ? (
                      <div className="input-group">
                        <input
                          type="text"
                          className="form-control"
                          placeholder="Collection URL"
                          readOnly
                          value={collection.url}
                        />
                        <div className="input-group-append">
                          <button>
                            <i className="icon-docs" />
                          </button>
                        </div>
                      </div>
                    ) : (
                      "- no URL found -"
                    )}
                  </p>
                  <p className="mt-3 mb-3">
                    {collection.description ? collection.description : "- no description found -"}
                  </p>
                </div>
              </div>
            </div>
            <div className="items four-box-column">
              <div className="px-0 mt-3 mr-3">
                <div className="card no-hover">
                  <div className="single-seller d-flex align-items-center">
                    <img
                      className="avatar-md rounded-circle"
                      src={collection.category?.image || categoryDefaultImg}
                      alt="Category Image"
                    />
                    <div className="seller-info ml-3">
                      <div className="seller">{collection.category?.name || "N/A"}</div>
                      <span>Category</span>
                    </div>
                  </div>
                </div>
              </div>

              <div className="px-0 my-3 mr-3">
                <div className="card no-hover">
                  <div className="single-seller d-flex align-items-center">
                    <Link to="/author">
                      <img
                        className="avatar-md rounded-circle"
                        src={collection.user?.profilePhoto || userDefaultImg}
                        alt="User Avatar"
                      />
                    </Link>
                    <div className="seller-info ml-3">
                      <Link className="seller mb-2" to="/author">
                        {collection.user?.username}
                      </Link>
                      <span>Creator</span>
                    </div>
                  </div>
                </div>
              </div>

              <div className="px-0 mt-3 mr-3">
                <div className="card no-hover">
                  <div className="single-seller d-flex align-items-center">
                    {/* <img
                      className="avatar-md rounded-circle"
                      src={collection.category?.image || categoryDefaultImg}
                    alt="Category Image"
                    /> */}
                    <div className="avatar-md rounded-circle">
                    <i class="fas fa-clone"/>
                    </div>
                    <div className="seller-info ml-3">
                      <div className="seller">{collection.category?.name || "N/A"}</div>
                      <span>Items</span>
                    </div>
                  </div>
                </div>
              </div>

              <div className="px-0 my-3">
                <div className="card no-hover">
                  <div className="single-seller d-flex align-items-center">
                    <Link to="/author">
                      {/* <img
                        className="avatar-md rounded-circle"
                        src={collection.user?.profilePhoto || userDefaultImg}
                        alt="User Avatar"
                      /> */}
                      <div className="avatar-md rounded-circle">
                      <i class="fas fa-users"/>
                      </div>
                    </Link>
                    <div className="seller-info ml-3">
                      <Link className="seller mb-2" to="/author">
                        {collection.user?.username}
                      </Link>
                      <span>Owners</span>
                    </div>
                  </div>
                </div>
              </div>
            </div>
            <div className="d-flex collection-wrapper">
                <FilterSearch />
              <div className="nfts-collection-wrapper">
                <Explore collectionId={collection._id} setLoader={getNftsLoader} />
              </div>
            </div>
          </div>
        )}
      </div>
    </section>
  );
};

const mapStateToProps = (state) => ({
  error: state.error,
  collection: state.collection,
});

export default connect(mapStateToProps, {
  beforeCollection,
  getCollection,
})(CollectionDetails);
