import { BEFORE_BID, GET_BIDS, CREATE_BID, DELETE_BID } from '../../redux/types';

const initialState = {
    bid: null,
    bids: null,
    pagination: null,
    deleteAuth: false,
    createAuth: false,
    getAuth: false
}

export default function (state = initialState, action) {
    switch (action.type) {
        case GET_BIDS:
            return {
                ...state,
                bid: action.payload.bid,
                getAuth: true
            }
        case CREATE_BID:
            return {
                ...state,
                bid: action.payload,
                createAuth: true
            }
        case DELETE_BID:
            return {
                ...state,
                bid: action.payload,
                deleteAuth: true
            }
        case BEFORE_BID:
            return {
                ...state,
                bid: null,
                bids: null,
                pagination: null,
                deleteAuth: false,
                createAuth: false,
                getAuth: false
            }
        default:
            return {
                ...state
            }
    }
}